@@ -0,0 +1,40 @@
+import { daysLeft, isExpired } from "./expiry.js";
+
+/** Builds a shelf summary report as of `now`. */
+export function buildReport(items, now = Date.now()) {
+  const active = [];
+  const expired = [];
+  for (const item of items) {
+    if (isExpired(item, now)) expired.push(item.name);
+    else active.push(item);
+  }
+  const tagCounts = {};
+  let units = 0;
+  for (const item of active) {
+    units += item.qty;
+    for (const tag of item.tags) {
+      tagCounts[tag] = (tagCounts[tag] || 0) + 1;
+    }
+  }
+  const byTag = {};
+  for (const tag of Object.keys(tagCounts).sort()) {
+    byTag[tag] = tagCounts[tag];
+  }
+  const expiringSoon = active
+    .filter((item) => daysLeft(item, now) <= 3)
+    .sort(
+      (a, b) =>
+        Date.parse(a.expires) - Date.parse(b.expires) ||
+        (a.name < b.name ? -1 : a.name > b.name ? 1 : 0),
+    )
+    .map((item) => item.name);
+  expired.sort();
+  return {
+    generatedAt: new Date(now).toISOString(),
+    total: active.length,
+    units,
+    byTag,
+    expiringSoon,
+    expired,
+  };
+}
